// no-op; using the handle afterwards is undefined behaviour.
//
// Options are copied into the session at creation time, so destroying an
// options object never affects sessions already built from it, and the object
// may be destroyed immediately after the create call returns.
//
// # Safety
//
// `opts` must be `NULL` or a handle from `vokra_session_options_create` that
// has not already been destroyed.
void vokra_session_options_destroy(struct vokra_session_options_t *opts);

// Selects the backend a session built from these options will run on.
//
// # Parameters
//
// - `opts`: options handle from `vokra_session_options_create`.
// - `backend`: a `vokra_backend_t` value (`VOKRA_BACKEND_CPU` = 0,
//   `_METAL` = 1, `_CUDA` = 2, `_VULKAN` = 3, `_WEBGPU` = 4). Any other value
//   is rejected.
//
// # Returns
//
// `VOKRA_OK`, or `VOKRA_ERROR_INVALID_ARGUMENT` for a NULL handle or an
// unknown `backend` value. **A rejected call changes nothing** — the object
// keeps the backend it had and stays usable.
//
// This setter deliberately does **not** check whether the selected backend
// exists on this machine: it records an intent, and probing a GPU would make a
// plain setter allocate a device. Availability is resolved when the session is
// created (`VOKRA_ERROR_BACKEND_UNAVAILABLE`), and can be queried up front
// with `vokra_backend_available`.
//
// # Safety
//
// `opts` must be a live handle from `vokra_session_options_create`, not used
// concurrently from another thread.
enum vokra_status_t vokra_session_options_set_backend(struct vokra_session_options_t *opts,
                                                      int32_t backend);

// Reports whether `backend` can actually be used by this build on this
// machine.
//
// `true` means the backend is compiled into this binary **and** its device /
// driver is present, so `vokra_session_create_*_with_options` will not reject
// it with `VOKRA_ERROR_BACKEND_UNAVAILABLE`. It does not promise that every
// model runs there: a backend that lacks a kernel some model needs still
// fails loudly at inference with `VOKRA_ERROR_UNSUPPORTED_OP`, never by
// falling back to the CPU (FR-EX-08).
//
// A query has no failure mode, so this returns a plain `bool`, leaves
// `vokra_last_error()` untouched, and answers `false` — rather than erroring —
// for a `backend` value outside `vokra_backend_t`.
//
// The probe genuinely opens the backend (a Metal device, the CUDA driver,
// `libvulkan`) and closes it again, so it is far cheaper than loading a model
// but is not free; cache the answer if you poll it in a UI loop.
bool vokra_backend_available(int32_t backend);

// Opens a full-duplex S2S session (Moshi = M4-06) on a session whose
// model injected a duplex engine.
//
// # Parameters
//
// - `session`: a live session handle (`vokra_session_create_from_file`
//   with a `moshi` GGUF).
// - `deterministic`: non-zero → greedy (temperature-0) sampling on both
//   decode channels (reproducible demos / parity).
// - `seed`: stochastic sampling seed (ignored when `deterministic`).
// - `aec_disabled_explicitly`: non-zero **explicitly** skips the echo
//   canceller (recorded-file input only — a loud warning is recorded on
//   the session; there is no silent variant). Zero requires the engine's
//   AEC wiring and fails loudly without it (FR-OP-60).
// - `playback_offset_samples`: echo-reference clock compensation for the
//   real playback latency (owner-tunable; 0 for file-driven use).
// - `out_duplex`: on `VOKRA_OK`, receives the new handle.
//
// # Returns
//
// `VOKRA_OK`, or a non-zero status (no duplex engine on this session,
// AEC posture violation, ...) with detail from `vokra_last_error()`.
//
// # Safety
//
// `session` must be a live session handle; `out_duplex` must be a valid,
// writable pointer.
enum vokra_status_t vokra_s2s_duplex_open(const struct vokra_session_t *session,
                                          int32_t deterministic,
                                          uint64_t seed,
                                          int32_t aec_disabled_explicitly,
                                          uint64_t playback_offset_samples,
                                          struct vokra_s2s_duplex_t **out_duplex);

// Mono samples per push/pull frame of `duplex` (size your PCM buffers
// with this — 1920 for the real 24 kHz / 12.5 Hz model).
//
// # Safety
//
// `duplex` must be a live duplex handle; `out_hop` valid and writable.
enum vokra_status_t vokra_s2s_frame_hop(const struct vokra_s2s_duplex_t *duplex,
                                        size_t *out_hop);

// PCM sample rate (Hz) of both duplex directions.
//
// # Safety
//
// `duplex` must be a live duplex handle; `out_rate` valid and writable.
enum vokra_status_t vokra_s2s_sample_rate(const struct vokra_s2s_duplex_t *duplex,
                                          uint32_t *out_rate);

// Feeds one mic frame (exactly `vokra_s2s_frame_hop` samples) through
// the input front (AEC unless explicitly disabled) and one model step.
//
// `out_emitted` (optional — may be `NULL`) receives non-zero once the
// model produced a frame for this push (after its delay warmup); pull it
// with `vokra_s2s_pull_audio`.
//
// # Safety
//
// `duplex` must be a live duplex handle owned by the calling thread;
// `pcm` must point to `len` readable floats; `out_emitted` must be
// `NULL` or writable.
enum vokra_status_t vokra_s2s_push_mic(struct vokra_s2s_duplex_t *duplex,
                                       const float *pcm,
                                       size_t len,
                                       int32_t *out_emitted);

// Pops the next model frame for playback into `out_pcm`
// (`capacity >= vokra_s2s_frame_hop` floats). `*out_len` is the sample
// count written — `0` means nothing is pending (delay warmup / caught
// up / flushed by a barge-in). Pulling is the playback hand-off: the
// frame is stamped into the echo-reference queue at this moment.
//
// # Safety
//
// `duplex` must be a live duplex handle owned by the calling thread;
// `out_pcm` must point to `capacity` writable floats; `out_len` must be
// valid and writable.
enum vokra_status_t vokra_s2s_pull_audio(struct vokra_s2s_duplex_t *duplex,
                                         float *out_pcm,
                                         size_t capacity,
                                         size_t *out_len);

// Copies the inner monologue accumulated so far (Moshi's self-generated
// transcript, display-rule filtered) into `buf` as NUL-terminated UTF-8.
//
// `*out_needed` always receives the byte length **including** the NUL;
// when `buf` is `NULL` or `buf_len` is too small, nothing is written and
// the call still returns `VOKRA_OK` — size with a first call, then
// fetch (the standard two-call string discipline).
//
// # Safety
//
// `duplex` must be a live duplex handle owned by the calling thread;
// `buf` must be `NULL` or `buf_len` writable bytes; `out_needed` valid
// and writable.
enum vokra_status_t vokra_s2s_text(const struct vokra_s2s_duplex_t *duplex,
                                   char *buf,
                                   size_t buf_len,
                                   size_t *out_needed);

// Creates a cross-thread barge-in handle for `duplex` (module docs —
// safe to fire from another thread while this one pushes/pulls).
//
// # Safety
//
// `duplex` must be a live duplex handle; `out_interrupt` valid and
// writable.
enum vokra_status_t vokra_s2s_interrupt_handle(const struct vokra_s2s_duplex_t *duplex,
                                               struct vokra_s2s_interrupt_t **out_interrupt);

// Requests barge-in (M3-14 semantics): the session flushes pending model
// output and resets its generation state at the next push/pull boundary;
// mic intake continues. Callable from any thread (the handle owns its
// own atomic flag — module docs).
//
// # Safety
//
// `interrupt` must be a live interrupt handle (not yet destroyed).
enum vokra_status_t vokra_s2s_interrupt(const struct vokra_s2s_interrupt_t *interrupt);

// Frees a barge-in handle. `NULL` is a no-op; double-free is undefined
// behaviour.
//
// # Safety
//
// `interrupt` must be `NULL` or a handle from
// `vokra_s2s_interrupt_handle` not already freed.
void vokra_s2s_interrupt_destroy(struct vokra_s2s_interrupt_t *interrupt);

// Frees a duplex session. `NULL` is a no-op; double-free is undefined
// behaviour. Outstanding interrupt handles stay valid (they only own an
// atomic flag) but firing them after destroy has no observer.
//
// # Safety
//
// `duplex` must be `NULL` or a handle from `vokra_s2s_duplex_open` not
// already freed.
void vokra_s2s_duplex_destroy(struct vokra_s2s_duplex_t *duplex);

// Copies the model's attribution text (FR-MD-09 — weights whose license
// requires display, e.g. Moshi / Mimi CC-BY 4.0) into `buf` as
// NUL-terminated UTF-8, with the two-call sizing discipline of
// `vokra_s2s_text`.
//
// `*out_needed == 0` (and nothing written) means the loaded model's
// weights carry **no** display obligation (permissive licenses) — an
// attribution-required weight always yields a non-empty text (the
// runtime falls back to a registry-derived string when the GGUF chunk is
// absent; M4-06-T23).
//
// # Safety
//
// `session` must be a live session handle; `buf` must be `NULL` or
// `buf_len` writable bytes; `out_needed` valid and writable.
enum vokra_status_t vokra_model_attribution(const struct vokra_session_t *session,
                                            char *buf,
                                            size_t buf_len,
                                            size_t *out_needed);

// Separates or enhances a complete mono waveform with the session's model.
//
// The returned allocation is stream-major `[stream][sample]`. Every stream
// has `out_num_samples_per_stream` samples. Free it with
// `vokra_audio_free(out_pcm, out_num_streams * out_num_samples_per_stream)`.
// All output pointers are written only on `VOKRA_OK`.
//
// # Safety
//
// `session` must be a live session handle, `pcm` must point at
// `num_samples` initialized `f32` values, and all output pointers must be
// writable locations of their declared type.
enum vokra_status_t vokra_separate(const struct vokra_session_t *session,
                                   const float *pcm,
                                   size_t num_samples,
                                   int32_t sample_rate,
                                   float **out_pcm,
                                   size_t *out_num_streams,
                                   size_t *out_num_samples_per_stream,
                                   int32_t *out_sample_rate);

// Loads a model from a GGUF file and creates an inference session on the CPU
// backend (FR-API-01).
//
// The architecture is detected from the GGUF's `vokra.model.arch` metadata and
// the matching native engine is injected: `whisper` → ASR, `silero-vad` → VAD,
// `piper-plus-mb-istft-vits2` → TTS. ONNX is never loaded (FR-LD-05).
//
// # Parameters
//
// - `path_utf8`: NUL-terminated UTF-8 path to the `.gguf` model file.
// - `out_session`: on `VOKRA_OK`, receives a new session handle to be freed
//   with `vokra_session_destroy`. Untouched on error.
//
// # Returns
//
// `VOKRA_OK`, or a non-zero status with the detail available from
// `vokra_last_error()` (missing file, unparsable GGUF, unknown arch, ...).
//
// # Safety
//
// `path_utf8` must be a valid NUL-terminated C string and `out_session` a
// valid, writable `vokra_session_t*` location.
enum vokra_status_t vokra_session_create_from_file(const char *path_utf8,
                                                   struct vokra_session_t **out_session);

// Loads a model from an in-memory GGUF buffer and creates an inference
// session on the CPU backend — the bytes-based twin of
// `vokra_session_create_from_file` (M4-02, prerelease ABI addition).
//
// The caller reads / downloads the `.gguf` bytes itself and hands them over;
// Vokra copies them once and never touches the filesystem. Primary model
// path on Unity WebGL, where StreamingAssets are HTTP-served (no `fopen`)
// and Rust-side fs syscalls are ABI-skewed under Unity-era Emscripten
// (ADR M4-02 §2/§3); valid — and useful — on every other platform too
// (e.g. Android APK assets without the `persistentDataPath` expansion).
//
// # Parameters
//
// - `data`: pointer to the first byte of the GGUF buffer. The buffer is
//   copied before this call returns; the caller may free it immediately
//   afterwards.
// - `len`: buffer length in bytes. Must be non-zero (an empty buffer is
//   never a valid GGUF and is rejected loudly).
// - `out_session`: on `VOKRA_OK`, receives a new session handle to be freed
//   with `vokra_session_destroy`. Untouched on error.
//
// # Returns
//
// `VOKRA_OK`, or a non-zero status with the detail available from
// `vokra_last_error()` (NULL/empty buffer, unparsable GGUF, unknown arch, ...).
//
// # Safety
//
// `data` must point at `len` valid, initialised bytes for the duration of
// the call, and `out_session` must be a valid, writable `vokra_session_t*`
// location.
enum vokra_status_t vokra_session_create_from_bytes(const uint8_t *data,
                                                    size_t len,
                                                    struct vokra_session_t **out_session);

// Loads a model from a GGUF file with explicit construction options — the
// backend-selectable sibling of `vokra_session_create_from_file` (design §3.3).
//
// Identical in every respect except that the session runs on the backend the
// options object selects. `vokra_session_create_from_file(path, out)` is
// exactly this call with `opts = NULL`.
//
// # Parameters
//
// - `path_utf8`: NUL-terminated UTF-8 path to the `.gguf` model file.
// - `opts`: options from `vokra_session_options_create`, or `NULL` for the
//   defaults (CPU backend). Borrowed for the duration of the call only: the
//   selections are copied into the session, so the options object may be
//   destroyed — or reused for another session — as soon as this returns.
// - `out_session`: on `VOKRA_OK`, receives a new session handle to be freed
//   with `vokra_session_destroy`. Untouched on error.
//
// # Returns
//
// `VOKRA_OK`, or a non-zero status with the detail available from
// `vokra_last_error()`:
//
// - `VOKRA_ERROR_BACKEND_UNAVAILABLE` — the selected backend is not compiled
//   into this build, or its device / driver is missing. Query it beforehand
//   with `vokra_backend_available`.
// - `VOKRA_ERROR_UNSUPPORTED_OP` — the backend exists, but this model's engine
//   has no path onto it. A session is **not** returned on the CPU instead
//   (FR-EX-08: no silent fall back).
// - the usual load failures (missing file, unparsable GGUF, unknown arch).
//
// # Safety
//
// `path_utf8` must be a valid NUL-terminated C string; `opts` must be `NULL`
// or a live options handle; `out_session` must be a valid, writable
// `vokra_session_t*` location.
enum vokra_status_t vokra_session_create_from_file_with_options(const char *path_utf8,
                                                                const struct vokra_session_options_t *opts,
                                                                struct vokra_session_t **out_session);

// Loads a model from an in-memory GGUF buffer with explicit construction
// options — the backend-selectable sibling of
// `vokra_session_create_from_bytes` (design §3.3).
//
// Identical in every respect except that the session runs on the backend the
// options object selects. `vokra_session_create_from_bytes(data, len, out)` is
// exactly this call with `opts = NULL`. This is the Unity WebGL model path
// (ADR M4-02 §3) gaining backend selection.
//
// # Parameters
//
// - `data` / `len`: the GGUF bytes, copied before this call returns; `len`
//   must be non-zero.
// - `opts`: options from `vokra_session_options_create`, or `NULL` for the
//   defaults (CPU backend). Borrowed for the duration of the call only.
// - `out_session`: on `VOKRA_OK`, receives a new session handle to be freed
//   with `vokra_session_destroy`. Untouched on error.
//
// # Returns
//
// As `vokra_session_create_from_file_with_options` (including
// `VOKRA_ERROR_BACKEND_UNAVAILABLE` / `VOKRA_ERROR_UNSUPPORTED_OP` —
// never a silent CPU fall back).
//
// # Safety
//
// `data` must point at `len` valid, initialised bytes for the duration of the
// call; `opts` must be `NULL` or a live options handle; `out_session` must be
// a valid, writable `vokra_session_t*` location.
enum vokra_status_t vokra_session_create_from_bytes_with_options(const uint8_t *data,
                                                                 size_t len,
                                                                 const struct vokra_session_options_t *opts,
                                                                 struct vokra_session_t **out_session);

// Retains the session, producing an independent handle that shares the same
// loaded model via an atomic ref count (FR-API-03).
//
// This is the C ABI atomic ref count: it clones the inner `Session` (a cheap
// atomic `Arc` bump), so the model is freed only when the last handle is passed
// to `vokra_session_destroy`. The new handle is safe to move to another thread
// (`Session` is `Send + Sync`).
//
// # Parameters
//
// - `session`: an existing session handle to retain.
// - `out_session`: on `VOKRA_OK`, receives a new handle to be freed with
//   `vokra_session_destroy`. Untouched on error.
//
// # Safety
//
// `session` must be a valid session handle and `out_session` a writable
// `vokra_session_t*` location.
enum vokra_status_t vokra_session_retain(const struct vokra_session_t *session,
                                         struct vokra_session_t **out_session);

// Frees a session handle from `vokra_session_create_from_file` /
// `vokra_session_retain`. `NULL` is a no-op; using the handle after this call
// is undefined behaviour. The model is freed when the last handle is destroyed.
//
// # Safety
//
// `session` must be `NULL` or a handle from `vokra_session_create_from_file`
// or `vokra_session_retain` that has not already been destroyed.
void vokra_session_destroy(struct vokra_session_t *session);

// Returns the Vokra runtime version as a static NUL-terminated UTF-8 string
// (the `vokra-capi` crate version). The pointer is static — never free it.
const char *vokra_version(void);

// Computes the speaker embedding of one mono reference utterance.
//
// The session must have been created from a speaker-encoder model (GGUF arch
// `campplus`, `xvector`, `ecapa_tdnn`, `wespeaker`, or `titanet-large`); any other model reports
// `VOKRA_ERROR_NOT_IMPLEMENTED`, the same task-mismatch posture as
// `vokra_asr_transcribe` on a TTS voice.
//
// # Parameters
//
// - `session`: a session holding a speaker-encoder model.
// - `pcm` / `num_samples`: mono `f32` samples in `[-1, 1]`. The clip must
//   cover at least one analysis frame (25 ms at 16 kHz).
// - `sample_rate`: sample rate of `pcm` in Hz. Must equal the rate the model's
//   front-end was trained at (16000 for CAM++, X-vector, ECAPA-TDNN,
//   WeSpeaker, and TitaNet-L); a mismatch is
//   rejected instead of resampled, because a silent resample would change the
//   embedding without telling the caller (FR-EX-08).
// - `out_embedding` / `out_capacity`: caller-owned destination array and its
//   length **in floats**. May be `NULL` / `0` to query the size only.
// - `out_written`: receives the embedding dimension — on success the number of
//   floats written, and on a too-small buffer the number of floats required.
//
// # Returns
//
// `VOKRA_OK` when the embedding was written, or
// `VOKRA_ERROR_INVALID_ARGUMENT` when `out_capacity` is too small — in which
// case `*out_written` still holds the required size, so the two-call idiom is:
//
// ```c
// size_t n = 0;
// vokra_speaker_embed(s, pcm, len, 16000, NULL, 0, &n);   /* INVALID_ARGUMENT, n = 192 */
// float *emb = malloc(n * sizeof(float));
// vokra_speaker_embed(s, pcm, len, 16000, emb, n, &n);    /* VOKRA_OK */
// ```
//
// Note that this differs from `vokra_s2s_text` / `vokra_model_attribution`,
// which report a short buffer as `VOKRA_OK`. Those return optional text a
// caller may legitimately skip; a truncated embedding is never useful, so it
// is an error here. `*out_written` is the one output written on that error
// path — every other failure leaves all outputs untouched.
//
// # Safety
//
// `session` must be a live session handle; `pcm` must point at `num_samples`
// valid floats (or be `NULL` when `num_samples` is 0); `out_embedding` must be
// `NULL` or point at `out_capacity` writable floats; `out_written` must be a
// valid, writable `size_t` location.
enum vokra_status_t vokra_speaker_embed(const struct vokra_session_t *session,
                                        const float *pcm,
                                        size_t num_samples,
                                        int32_t sample_rate,
                                        float *out_embedding,
                                        size_t out_capacity,
                                        size_t *out_written);

// Compares two speaker embeddings (FR-OP-81).
//
// Takes no session: it is arithmetic on two vectors, so embeddings can be
// stored (in a database, a save file) and matched later without a model
// loaded. The inputs need not be L2-normalized — `vokra_speaker_embed`
// output goes straight in.
//
// # Parameters
//
// - `a` / `a_len`, `b` / `b_len`: the two embeddings. They must be the same
//   non-zero length, and neither may be all zeros (a zero vector has no
//   direction).
// - `threshold`: the accept/reject operating point, used **only** when
//   `out_same_speaker` is non-`NULL`. It must be finite.
// - `out_similarity`: receives the cosine similarity in `[-1, 1]` (1 = same
//   direction). Required.
// - `out_same_speaker`: optional. When non-`NULL`, receives
//   `similarity >= threshold`. Pass `NULL` to get the similarity only —
//   Vokra deliberately does not ship a default threshold (ADR M4-20 §D-4);
//   take the operating point from your model's published EER.
//
// # Returns
//
// `VOKRA_OK`, or `VOKRA_ERROR_INVALID_ARGUMENT` for a NULL required pointer,
// mismatched or empty lengths, a zero-norm embedding, or a non-finite
// `threshold` when a decision was requested.
//
// # Safety
//
// `a` / `b` must point at `a_len` / `b_len` valid floats; `out_similarity`
// must be a valid, writable `float` location; `out_same_speaker` must be
// `NULL` or a valid, writable `bool` location.
enum vokra_status_t vokra_speaker_verify(const float *a,
                                         size_t a_len,
                                         const float *b,
                                         size_t b_len,
                                         float threshold,
                                         float *out_similarity,
                                         bool *out_same_speaker);

// Opens a VAD stream over a session (FR-API-01 / FR-ST-02).
//
// # Parameters
//
// - `session`: a session created from a Silero VAD GGUF.
// - `sample_rate`: the stream sample rate in Hz (Silero accepts 8000 or
//   16000; other rates are rejected by the first `vokra_stream_push_pcm`).
// - `out_stream`: on `VOKRA_OK`, receives a stream handle freed with
//   `vokra_stream_destroy`. The stream retains the session, so it keeps the
//   model alive even after `vokra_session_destroy`.
//
// Returns `VOKRA_ERROR_NOT_IMPLEMENTED` if the session's model is not a VAD
// model (no VAD engine was injected).
//
// # Safety
//
// `session` must be a valid session handle and `out_stream` a writable
// `vokra_stream_t*` location.
enum vokra_status_t vokra_stream_open(const struct vokra_session_t *session,
                                      int32_t sample_rate,
                                      struct vokra_stream_t **out_stream);

// Pushes mono `f32` PCM into a VAD stream (FR-API-01). Each completed frame's
// event is enqueued on the stream's ring; drain them with `vokra_stream_poll`
// or `vokra_stream_poll_events`. A trailing partial frame is held internally.
//
// # Safety
//
// `stream` must be a valid stream handle and `pcm` valid for `num_samples`
// reads (or `NULL` when `num_samples == 0`).
enum vokra_status_t vokra_stream_push_pcm(struct vokra_stream_t *stream,
                                          const float *pcm,
                                          size_t num_samples);

// Drains up to `capacity` buffered speech probabilities into `out_probs`
// (FR-API-01). Non-blocking: writes `*out_count` = number written (0 if none
// pending). `out_probs` may be `NULL` only when `capacity == 0`.
//
// # Safety
//
// `stream` must be a valid stream handle, `out_probs` valid for `capacity`
// writes (or `NULL` when `capacity == 0`), and `out_count` a writable
// `size_t` location.
enum vokra_status_t vokra_stream_poll(struct vokra_stream_t *stream,
                                      float *out_probs,
                                      size_t capacity,
                                      size_t *out_count);

// Drains up to `capacity` typed events into `out_events` (M1-08). Non-blocking:
// writes `*out_count` = number written. `out_events` may be `NULL` only when
// `capacity == 0`. This is the generalized poll; `vokra_stream_poll` is the
// f32-probability fast path over the same ring.
//
// # Safety
//
// `stream` must be a valid stream handle, `out_events` valid for `capacity`
// writes (or `NULL` when `capacity == 0`), and `out_count` a writable
// `size_t` location.
enum vokra_status_t vokra_stream_poll_events(struct vokra_stream_t *stream,
                                             struct vokra_event_t *out_events,
                                             size_t capacity,
                                             size_t *out_count);

// Barge-in: flushes the current chunk output, drains the stream's ring
// (when the consumer half is still on this stream), resets the stepper's
// hidden state, and clears the barge-in flag — all synchronously, so the
// next `vokra_stream_push_pcm` is accepted in a clean state (M3-14 /
// FR-ST-03).
//
// This is the C-ABI counterpart of [`Stream::interrupt`](vokra_core::Stream::interrupt).
// A bare (no-stepper) stream is a documented no-op that still returns
// `VOKRA_OK`.
//
// # Thread safety
//
// `vokra_stream_interrupt` takes exclusive access to the stream handle for
// the duration of the call (mirroring the `&mut self` receiver on the Rust
// API). A C caller that shares one `vokra_stream_t*` across threads MUST
// serialise access — the underlying barge-in flag is lock-free, but the
// handler mutates the ring and stepper state. For cross-thread barge-in
// without ownership of the stream, hold the stream on one thread and drive
// interrupts through a Rust-side [`InterruptHandle`](vokra_core::InterruptHandle);
// a dedicated C ABI for the cross-thread handle is a follow-on (M3-16 v0.9
// ABI changelog).
//
// # Safety
//
// `stream` must be a valid stream handle from `vokra_stream_open` and must
// not be aliased on another thread for the duration of the call.
enum vokra_status_t vokra_stream_interrupt(struct vokra_stream_t *stream);

// Frees a stream handle from `vokra_stream_open`. `NULL` is a no-op.
//
// # Safety
//
// `stream` must be `NULL` or a handle from `vokra_stream_open` not already
// destroyed.
void vokra_stream_destroy(struct vokra_stream_t *stream);

// Synthesizes speech PCM from UTF-8 text using the session's TTS engine
// (FR-API-01, piper-plus native path).
//
// # Parameters
//
// - `session`: a session created from a piper-plus voice GGUF.
// - `text_utf8`: NUL-terminated UTF-8 text to synthesize.
// - `out_pcm`: on `VOKRA_OK`, receives a Vokra-owned mono `f32` buffer (values
//   in `[-1, 1]`) to be freed with `vokra_audio_free(*out_pcm, *out_num_samples)`.
// - `out_num_samples`: receives the sample count of `*out_pcm`.
// - `out_sample_rate`: receives the output sample rate in Hz.
//
// All three out-params are written only on `VOKRA_OK`.
//
// # Safety
//
// `session` must be a valid session handle, `text_utf8` a valid C string, and
// the three out-pointers writable locations of the matching type.
enum vokra_status_t vokra_tts_synthesize(const struct vokra_session_t *session,
                                         const char *text_utf8,
                                         float **out_pcm,
                                         size_t *out_num_samples,
                                         int32_t *out_sample_rate);

// Frees a PCM buffer returned by `vokra_tts_synthesize`. Pass the pointer and
// the sample count from the same call. `NULL` is a no-op; double-free is
// undefined behaviour.
//
// # Safety
//
// `pcm` must be `NULL`, or the `*out_pcm` from a `vokra_tts_synthesize` call
// with the matching `num_samples`, not already freed.
void vokra_audio_free(float *pcm, size_t num_samples);

